"""Every case in conformance/indicators.v1.json, generated by the TypeScript reference."""

import json
import unittest
from pathlib import Path

import super_chart as ta

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "indicators.v1.json").read_text())

CALLS = {
    "sma": lambda a: ta.sma(a["src"], a["len"]),
    "ema": lambda a: ta.ema(a["src"], a["len"]),
    "rma": lambda a: ta.rma(a["src"], a["len"]),
    "rsi": lambda a: ta.rsi(a["src"], a["len"]),
    "stdev": lambda a: ta.stdev(a["src"], a["len"]),
    "bollinger": lambda a: ta.bollinger(a["src"], a["len"], a["mult"]),
    "macd": lambda a: ta.macd(a["src"], a["fast"], a["slow"], a["signal"]),
    "trueRange": lambda a: ta.true_range(a["high"], a["low"], a["close"]),
    "atr": lambda a: ta.atr(a["high"], a["low"], a["close"], a["len"]),
    "wma": lambda a: ta.wma(a["src"], a["len"]),
    "hma": lambda a: ta.hma(a["src"], a["len"]),
    "vwma": lambda a: ta.vwma(a["src"], a["volume"], a["len"]),
    "dev": lambda a: ta.dev(a["src"], a["len"]),
    "highest": lambda a: ta.highest(a["src"], a["len"]),
    "lowest": lambda a: ta.lowest(a["src"], a["len"]),
    "change": lambda a: ta.change(a["src"], int(a["len"])),
    "mom": lambda a: ta.mom(a["src"], int(a["len"])),
    "roc": lambda a: ta.roc(a["src"], int(a["len"])),
    "crossover": lambda a: ta.crossover(a["a"], a["b"]),
    "crossunder": lambda a: ta.crossunder(a["a"], a["b"]),
    "cross": lambda a: ta.cross(a["a"], a["b"]),
    "cum": lambda a: ta.cum(a["src"]),
    "barssince": lambda a: ta.barssince(a["cond"]),
    "obv": lambda a: ta.obv(a["close"], a["volume"]),
    "vwap": lambda a: ta.vwap(a["high"], a["low"], a["close"], a["volume"]),
    "cci": lambda a: ta.cci(a["high"], a["low"], a["close"], a["len"]),
    "mfi": lambda a: ta.mfi(a["high"], a["low"], a["close"], a["volume"], a["len"]),
    "stochK": lambda a: ta.stoch_k(a["high"], a["low"], a["close"], a["len"]),
    "stoch": lambda a: ta.stoch(a["src"], a["len"]),
    "stochRsi": lambda a: ta.stoch_rsi(a["src"], a["rsiLen"], a["stochLen"], a["kLen"], a["dLen"]),
    "bbPercent": lambda a: ta.bb_percent(a["src"], a["len"], a["mult"]),
    "sar": lambda a: ta.sar(a["high"], a["low"], a["start"], a["inc"], a["max"]),
    "keltner": lambda a: ta.keltner(a["high"], a["low"], a["close"], a["len"], a["mult"], a["atrLen"]),
}


def close(got, want, tolerance):
    if want is None or got is None:
        return want is None and got is None
    return abs(got - want) <= tolerance * max(1.0, abs(want))


class Conformance(unittest.TestCase):
    def check(self, got, want, tolerance, label):
        if isinstance(want, dict):
            self.assertEqual(sorted(got), sorted(want), label)
            for key in want:
                self.check(got[key], want[key], tolerance, f"{label}.{key}")
            return
        self.assertEqual(len(got), len(want), label)
        for i, (g, w) in enumerate(zip(got, want, strict=True)):
            self.assertTrue(close(g, w, tolerance), f"{label}[{i}]: {g} != {w}")

    def test_cases(self):
        self.assertEqual(set(CALLS), {c["fn"] for c in DATA["cases"]})
        for index, case in enumerate(DATA["cases"]):
            with self.subTest(i=index, fn=case["fn"]):
                self.check(CALLS[case["fn"]](case["args"]), case["expect"], case["tolerance"], f"{case['fn']}#{index}")

    def test_enough_cases(self):
        self.assertGreaterEqual(len(DATA["cases"]), 300)


if __name__ == "__main__":
    unittest.main()
